SELECT 'ActiveLanIds', '(all, de-duplicated)', (SELECT COUNT(*) FROM (SELECT "LanId" FROM "src_cwp_ecr"."ActiveLanIds" UNION ALL SELECT "LanId" FROM "src_cwp_opspj3"."ActiveLanIds" UNION ALL SELECT "LanId" FROM "src_cwp_opspj"."ActiveLanIds" UNION ALL SELECT "LanId" FROM "src_cwp_procon"."ActiveLanIds" UNION ALL SELECT "LanId" FROM "src_cwp_opspj2"."ActiveLanIds" UNION ALL SELECT "LanId" FROM "src_cwp_opspj4"."ActiveLanIds" UNION ALL SELECT "LanId" FROM "src_cwp_xrl"."ActiveLanIds" UNION ALL SELECT "LanId" FROM "src_cwp"."ActiveLanIds" UNION ALL SELECT "LanId" FROM "src_cwp2"."ActiveLanIds") a), (SELECT COUNT(*) FROM (SELECT "LanId" FROM "src_cwp_ecr"."ActiveLanIds" UNION SELECT "LanId" FROM "src_cwp_opspj3"."ActiveLanIds" UNION SELECT "LanId" FROM "src_cwp_opspj"."ActiveLanIds" UNION SELECT "LanId" FROM "src_cwp_procon"."ActiveLanIds" UNION SELECT "LanId" FROM "src_cwp_opspj2"."ActiveLanIds" UNION SELECT "LanId" FROM "src_cwp_opspj4"."ActiveLanIds" UNION SELECT "LanId" FROM "src_cwp_xrl"."ActiveLanIds" UNION SELECT "LanId" FROM "src_cwp"."ActiveLanIds" UNION SELECT "LanId" FROM "src_cwp2"."ActiveLanIds") a), (SELECT COUNT(*) FROM public."ActiveLanIds")
UNION ALL
SELECT 'Folder_Structure_Final_Analysis', '(all)', (SELECT COUNT(*) FROM (SELECT 1 FROM "src_cwp_ecr"."Folder_Structure_Final_Analysis" UNION ALL SELECT 1 FROM "src_cwp_opspj3"."Folder_Structure_Final_Analysis" UNION ALL SELECT 1 FROM "src_cwp_opspj"."Folder_Structure_Final_Analysis" UNION ALL SELECT 1 FROM "src_cwp_procon"."Folder_Structure_Final_Analysis" UNION ALL SELECT 1 FROM "src_cwp_opspj2"."Folder_Structure_Final_Analysis" UNION ALL SELECT 1 FROM "src_cwp_opspj4"."Folder_Structure_Final_Analysis" UNION ALL SELECT 1 FROM "src_cwp_xrl"."Folder_Structure_Final_Analysis" UNION ALL SELECT 1 FROM "src_cwp"."Folder_Structure_Final_Analysis") a), (SELECT COUNT(*) FROM (SELECT 1 FROM "src_cwp_ecr"."Folder_Structure_Final_Analysis" UNION ALL SELECT 1 FROM "src_cwp_opspj3"."Folder_Structure_Final_Analysis" UNION ALL SELECT 1 FROM "src_cwp_opspj"."Folder_Structure_Final_Analysis" UNION ALL SELECT 1 FROM "src_cwp_procon"."Folder_Structure_Final_Analysis" UNION ALL SELECT 1 FROM "src_cwp_opspj2"."Folder_Structure_Final_Analysis" UNION ALL SELECT 1 FROM "src_cwp_opspj4"."Folder_Structure_Final_Analysis" UNION ALL SELECT 1 FROM "src_cwp_xrl"."Folder_Structure_Final_Analysis" UNION ALL SELECT 1 FROM "src_cwp"."Folder_Structure_Final_Analysis") a), (SELECT COUNT(*) FROM public."Folder_Structure_Final_Analysis")
) v;

\echo '=== Row reconciliation ==='
SELECT * FROM verify_result ORDER BY status DESC, table_name, source_db;

\echo '=== SiteId check: every non-empty SiteName must carry the matching SiteId ==='
CREATE TEMP TABLE verify_site AS
SELECT 'Files' AS table_name, COUNT(*) FILTER (WHERE x."SiteName" <> '') AS rows_with_site,
       COUNT(*) FILTER (WHERE x."SiteName" <> '' AND (st."SiteName" IS DISTINCT FROM x."SiteName")) AS wrong_site_id
FROM public."Files" x LEFT JOIN public."Sites" st ON st."SiteId" = x."SiteId"
UNION ALL
SELECT 'Metadata' AS table_name, COUNT(*) FILTER (WHERE x."SiteName" <> '') AS rows_with_site,
       COUNT(*) FILTER (WHERE x."SiteName" <> '' AND (st."SiteName" IS DISTINCT FROM x."SiteName")) AS wrong_site_id
FROM public."Metadata" x LEFT JOIN public."Sites" st ON st."SiteId" = x."SiteId"
UNION ALL
SELECT 'Permissions' AS table_name, COUNT(*) FILTER (WHERE x."SiteName" <> '') AS rows_with_site,
       COUNT(*) FILTER (WHERE x."SiteName" <> '' AND (st."SiteName" IS DISTINCT FROM x."SiteName")) AS wrong_site_id
FROM public."Permissions" x LEFT JOIN public."Sites" st ON st."SiteId" = x."SiteId"
UNION ALL
SELECT 'ADGroups' AS table_name, COUNT(*) FILTER (WHERE x."SiteName" <> '') AS rows_with_site,
       COUNT(*) FILTER (WHERE x."SiteName" <> '' AND (st."SiteName" IS DISTINCT FROM x."SiteName")) AS wrong_site_id
FROM public."ADGroups" x LEFT JOIN public."Sites" st ON st."SiteId" = x."SiteId"
UNION ALL
SELECT 'ADGroupMembers' AS table_name, COUNT(*) FILTER (WHERE x."SiteName" <> '') AS rows_with_site,
       COUNT(*) FILTER (WHERE x."SiteName" <> '' AND (st."SiteName" IS DISTINCT FROM x."SiteName")) AS wrong_site_id
FROM public."ADGroupMembers" x LEFT JOIN public."Sites" st ON st."SiteId" = x."SiteId"
UNION ALL
SELECT 'PermissionSets' AS table_name, COUNT(*) FILTER (WHERE x."SiteName" <> '') AS rows_with_site,
       COUNT(*) FILTER (WHERE x."SiteName" <> '' AND (st."SiteName" IS DISTINCT FROM x."SiteName")) AS wrong_site_id
FROM public."PermissionSets" x LEFT JOIN public."Sites" st ON st."SiteId" = x."SiteId"
UNION ALL
SELECT 'FolderPermissions' AS table_name, COUNT(*) FILTER (WHERE x."SiteName" <> '') AS rows_with_site,
       COUNT(*) FILTER (WHERE x."SiteName" <> '' AND (st."SiteName" IS DISTINCT FROM x."SiteName")) AS wrong_site_id
FROM public."FolderPermissions" x LEFT JOIN public."Sites" st ON st."SiteId" = x."SiteId"
UNION ALL
SELECT 'PermissionMatrixSummaries' AS table_name, COUNT(*) FILTER (WHERE x."SiteName" <> '') AS rows_with_site,
       COUNT(*) FILTER (WHERE x."SiteName" <> '' AND (st."SiteName" IS DISTINCT FROM x."SiteName")) AS wrong_site_id
FROM public."PermissionMatrixSummaries" x LEFT JOIN public."Sites" st ON st."SiteId" = x."SiteId"
UNION ALL
SELECT 'MigrationTasks' AS table_name, COUNT(*) FILTER (WHERE x."SiteName" <> '') AS rows_with_site,
       COUNT(*) FILTER (WHERE x."SiteName" <> '' AND (st."SiteName" IS DISTINCT FROM x."SiteName")) AS wrong_site_id
FROM public."MigrationTasks" x LEFT JOIN public."Sites" st ON st."SiteId" = x."SiteId"
UNION ALL
SELECT 'ScanProgress' AS table_name, COUNT(*) FILTER (WHERE x."SiteName" <> '') AS rows_with_site,
       COUNT(*) FILTER (WHERE x."SiteName" <> '' AND (st."SiteName" IS DISTINCT FROM x."SiteName")) AS wrong_site_id
FROM public."ScanProgress" x LEFT JOIN public."Sites" st ON st."SiteId" = x."SiteId"
UNION ALL
SELECT 'FolderInheritanceBreaks' AS table_name, COUNT(*) FILTER (WHERE x."SiteName" <> '') AS rows_with_site,
       COUNT(*) FILTER (WHERE x."SiteName" <> '' AND (st."SiteName" IS DISTINCT FROM x."SiteName")) AS wrong_site_id
FROM public."FolderInheritanceBreaks" x LEFT JOIN public."Sites" st ON st."SiteId" = x."SiteId"
UNION ALL
SELECT 'MigrationTasks_Parsed' AS table_name, COUNT(*) FILTER (WHERE x."SiteName" <> '') AS rows_with_site,
       COUNT(*) FILTER (WHERE x."SiteName" <> '' AND (st."SiteName" IS DISTINCT FROM x."SiteName")) AS wrong_site_id
FROM public."MigrationTasks_Parsed" x LEFT JOIN public."Sites" st ON st."SiteId" = x."SiteId"
UNION ALL
SELECT 'Folder_Structure_Final_Analysis' AS table_name, COUNT(*) FILTER (WHERE x."SiteName" <> '') AS rows_with_site,
       COUNT(*) FILTER (WHERE x."SiteName" <> '' AND (st."SiteName" IS DISTINCT FROM x."SiteName")) AS wrong_site_id
FROM public."Folder_Structure_Final_Analysis" x LEFT JOIN public."Sites" st ON st."SiteId" = x."SiteId";
SELECT * FROM verify_site ORDER BY table_name;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM verify_site WHERE wrong_site_id > 0) THEN
    RAISE EXCEPTION 'VERIFY FAILED: SiteId does not match SiteName (see above)';
  END IF;
END $$;

\echo '=== Conflict log summary ==='
SELECT table_name, source_db, action, COUNT(*) FROM _merge.conflict_log GROUP BY 1, 2, 3 ORDER BY 1, 2, 3;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM verify_result WHERE status <> 'OK') THEN
    RAISE EXCEPTION 'VERIFY FAILED: see MISMATCH rows above';
  END IF;
  RAISE NOTICE 'VERIFY OK: every source row is loaded or accounted for in _merge.conflict_log';
END $$;
